/// <summary>
/// Kleber customer address predictive search response contract
/// </summary>
[DataContractAttribute('Result')]
class METKleberCustAddressPredictiveSearchResponseContract
{
    LogisticsAddressStreet addressLine;
    LogisticsAddressCityName locality;
    LogisticsAddressStateId state;
    LogisticsAddressZipCodeId postcode;
    str requestId, recordId;

}

Method.Source:
/// <summary>
/// Get or set Address line
/// </summary>
/// <param name = "_addressLine">Address line</param>
/// <returns>Address line</returns>
[DataMemberAttribute("AddressLine")]
public LogisticsAddressStreet parmAddressLine(str _addressLine = addressLine)
{
    addressLine = _addressLine;
    return addressLine;
}

/// <summary>
/// Get or set RequestId
/// </summary>
/// <param name = "_requestId">requestId</param>
/// <returns>requestId</returns>
[DataMemberAttribute("RequestId")]
public str parmRequestId(str _requestId = requestId)
{
    requestId = _requestId;
    return requestId;
}

/// <summary>
/// Get or set Locality
/// </summary>
/// <param name = "_locality">Locality</param>
/// <returns>Locality</returns>
[DataMemberAttribute("Locality")]
public LogisticsAddressCityName parmLocality(str _locality = locality)
{
    locality = _locality;
    return locality;
}

/// <summary>
/// Get or set state
/// </summary>
/// <param name = "_state">state</param>
/// <returns>state</returns>
[DataMemberAttribute("State")]
public LogisticsAddressStateId parmState(str _state = state)
{
    state = _state;
    return state;
}

/// <summary>
/// Get or set Postcode
/// </summary>
/// <param name = "_postcode">postcode</param>
/// <returns>postcode</returns>
[DataMemberAttribute("Postcode")]
public LogisticsAddressZipCodeId parmPostcode(str _postcode = postcode)
{
    postcode = _postcode;
    return postcode;
}

/// <summary>
/// Get or set recordId
/// </summary>
/// <param name = "_recordId">recordId</param>
/// <returns>recordId</returns>
[DataMemberAttribute("RecordId")]
public str parmRecordId(str _recordId = recordId)
{
    recordId = _recordId;
    return recordId;
}
